# Тесты для дефектов #471/#472/#473 (двусторонние: FP обязан молчать, TP — ловить).
# КАЖДАЯ функция здесь — либо ложное обвинение, которое обязано ИСЧЕЗНУТЬ,
# либо настоящая ошибка, которая обязана ОСТАТЬСЯ. Если убрать любую из
# «молчащих» — гейт покажет регресс; если «заглушить» проверку целиком —
# настоящие перестанут ловиться, и это тоже видно.


def gcd_guarded(a, b):
    """#471a: гард в ветви `else` (было: ложный [CRASH PATH] b == 0)."""
    if b == 0:
        return a
    else:
        return gcd_guarded(a % b, b)


def gcd_no_else(a, b):
    """#471a (контроль той же правки): форма без `else` — тоже молчит."""
    if b == 0:
        return a
    return gcd_no_else(a % b, b)


def gcd_unguarded(a, b):
    """TP-КОНТРОЛЬ: гарда нет вовсе — обвинение обязано ОСТАТЬСЯ ([CRASH PATH])."""
    return a % b


def index_after_loop(items, i):
    """#473: индекс зависит от переменной, изменённой в ЦИКЛЕ -> Белнап N.

    Длина `items` известна (литерала нет, но есть `len(items)` — не важно):
    важно, что `total` меняется в цикле, поэтому свидетельство может быть
    недостижимо. Это ЗАМЕТКА, а не находка (`#473`).
    """
    total = 0
    for k in range(3):
        total += k
    return items[total]


def arr_unguarded(i):
    """TP-КОНТРОЛЬ для #473: литеральная длина + параметр-индекс -> [BOUNDS PATH]."""
    data = [10, 20, 30]
    return data[i]
